"""Printable invoice for simulated INR/USD checkout; all display fields are escaped."""
from html import escape
from decimal import Decimal
from datetime import datetime
from zoneinfo import ZoneInfo
from uuid import uuid4


def render_invoice(lines,assessment_date,invoice_number=None,currency='INR',price_note=''):
    if currency not in {'USD','INR'}:raise ValueError('Unsupported invoice currency.')
    symbol='$' if currency=='USD' else '₹'
    number=invoice_number or 'SC-'+uuid4().hex[:10].upper()
    stamp=datetime.now(ZoneInfo('Asia/Kolkata')).strftime('%d %b %Y, %I:%M %p IST')
    regular=sum(Decimal(str(r[f'Regular ({currency})'])) for r in lines)
    payable=sum(Decimal(str(r[f'Payable ({currency})'])) for r in lines)
    def money(value):return f'{symbol}{Decimal(str(value)):,.2f}'
    rows=''.join(f'''<tr><td>{n}</td><td><strong>{escape(str(r['Item']))}</strong><small>{escape(str(r.get('Batches','')))}</small></td><td>{escape(str(r['Quantity']))}<small>{escape('Combo discount covers '+str(r['Discounted quantity'])) if r.get('Discounted quantity') and r['Discounted quantity']!='0 g' else ''}</small></td><td class="num">{money(r[f'Regular ({currency})'])}</td><td class="num">{money(r[f'Savings ({currency})'])}</td><td class="num">{money(r[f'Payable ({currency})'])}</td></tr>''' for n,r in enumerate(lines,1))
    return f'''<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Smart Cart invoice {escape(number)}</title><style>
*{{box-sizing:border-box}}body{{margin:0;background:#eef2f6;color:#203442;font:14px Arial,sans-serif;line-height:1.5}}main{{max-width:980px;margin:20px auto;padding:34px;background:white;border:1px solid #dbe3e9;border-radius:10px}}header{{display:flex;justify-content:space-between;gap:20px;border-bottom:3px solid #167565;padding-bottom:20px}}h1,h2,p{{margin:4px 0}}h1{{color:#167565}}.meta{{text-align:right}}.badge{{display:inline-block;background:#fff0c7;color:#745a16;padding:4px 9px;border-radius:4px;font-size:11px}}.details{{margin:20px 0;display:flex;justify-content:space-between;gap:20px}}small{{display:block;color:#647681;font-size:11px}}table{{width:100%;border-collapse:collapse}}th{{background:#edf6f3;text-align:left;font-size:11px;padding:10px}}td{{padding:12px 10px;border-bottom:1px solid #e3eaee;vertical-align:top}}.num{{text-align:right;white-space:nowrap}}.totals{{max-width:350px;margin:24px 0 24px auto}}.row{{display:flex;justify-content:space-between;padding:6px 0}}.grand{{border-top:2px solid #167565;font-size:21px;font-weight:bold}}footer{{font-size:12px;color:#526674;border-top:1px solid #dbe3e9;padding-top:16px}}.toolbar{{max-width:980px;margin:16px auto;text-align:right}}button{{border:0;border-radius:5px;padding:10px 16px;background:#167565;color:white;cursor:pointer}}.wrap{{overflow-x:auto}}
@media(max-width:650px){{main{{padding:15px}}header,.details{{flex-direction:column}}.meta{{text-align:left}}}}@media print{{@page{{size:A4;margin:14mm}}body{{background:white}}main{{border:0;padding:0;margin:0;max-width:none}}.toolbar{{display:none}}thead{{display:table-header-group}}tr,.totals,footer{{break-inside:avoid}}}}
</style></head><body><div class="toolbar"><button onclick="window.print()">Print / Save as PDF</button></div><main><header><div><h1>SMART CART</h1><p>Prepared-component demonstration</p><span class="badge">SIMULATED CHECKOUT</span></div><div class="meta"><h2>INVOICE</h2><p>{escape(number)}</p><small>Issued {stamp}</small></div></header><section class="details"><div><strong>Customer</strong><p>Demo customer</p></div><div><strong>Assessment date</strong><p>{escape(str(assessment_date))}</p><p>Currency: {currency}</p></div></section><div class="wrap"><table><thead><tr><th>#</th><th>Item / combo</th><th>Quantity</th><th class="num">Regular</th><th class="num">Discount</th><th class="num">Amount</th></tr></thead><tbody>{rows}</tbody></table></div><section class="totals"><div class="row"><span>Regular subtotal</span><span>{money(regular)}</span></div><div class="row"><span>Combo savings</span><span>−{money(regular-payable)}</span></div><div class="row grand"><span>Demo total</span><span>{money(payable)}</span></div></section><footer><strong>Demonstration document — not a tax invoice or proof of payment.</strong><p>{escape(price_note)}</p><p>No payment was collected; no stock was reserved or deducted. Taxes and delivery are not calculated. This invoice records the confirmed cart snapshot.</p></footer></main></body></html>'''
